files.test_stats3.py:
import unittest

from stats3 import average, size, total


class StatsTest(unittest.TestCase):
    def test_total(self):
        self.assertEqual(total([1, 2, 3]), 6)

    def test_average(self):
        self.assertEqual(average([2, 4, 6]), 4)

    def test_size(self):
        self.assertEqual(size([7, 8]), 2)


if __name__ == '__main__':
    unittest.main()

